using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class DestructionGeometryOperations:RefCounted
{
    private readonly ModelGeometryOperations _geometry=new();private readonly ModelMeshOperations _meshes=new();private readonly ModelPrimitives _primitives=new();
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private static bool Fracture(int kind)=>kind is 0 or 1 or 2 or 3 or 6 or 7 or 8;
    public bool closed(Resource mesh){var snapshot=new ModelMeshOperations.Snapshot(mesh);return snapshot.Faces.Length>0&&_meshes.validate(mesh,true).Length==0&&ModelGeometryOperations.Edges(snapshot.Faces).All(edge=>edge.Faces.Count==2);}
    public double volume(Resource mesh){var data=new ModelMeshOperations.Snapshot(mesh);double result=0;for(int f=0;f<data.Faces.Length;f++){var face=data.Faces[f];var indices=data.Triangles(f);for(int i=0;i<indices.Length;i+=3){var a=data.Vertices[face[indices[i]]];var b=data.Vertices[face[indices[i+1]]];var c=data.Vertices[face[indices[i+2]]];result+=a.Dot(b.Cross(c))/6.0;}}return Math.Abs(result);}
    public Resource cut(Resource mesh,Vector3 normal,double distance,int interior){var result=_geometry.clip_plane(mesh,normal,distance);var data=new ModelMeshOperations.Snapshot(result);var degenerate=new List<int>();for(int f=0;f<data.Faces.Length;f++)if(data.Normal(f).LengthSquared()<.5)degenerate.Add(f);if(degenerate.Count>0){result=_geometry.remove_faces(result,degenerate.ToArray());data=new ModelMeshOperations.Snapshot(result);}var materials=(int[])data.Materials.Clone();for(int f=0;f<data.Faces.Length;f++){bool cap=true;foreach(int i in data.Faces[f])if(Math.Abs(normal.Dot(data.Vertices[i])-distance)>.00003){cap=false;break;}if(cap)materials[f]=interior;}result.Set("materials",materials);return result;}
    private List<Resource> Split(Resource mesh,Vector3 normal,Vector3 point,int interior){var result=new List<Resource>();normal=normal.Normalized();if(normal.IsZeroApprox())normal=Vector3.Right;foreach(float sign in new[]{1f,-1f}){var piece=cut(mesh,normal*sign,point.Dot(normal)*sign,interior);if(piece.Get("faces").AsGodotArray().Count>0&&_meshes.validate(piece,true).Length==0)result.Add(piece);}return result;}
    public GArray split(Resource mesh,Vector3 normal,Vector3 point,int interior){var result=new GArray();foreach(var piece in Split(mesh,normal,point,interior))result.Add(piece);return result;}
    private List<Resource> Subtract(Resource mesh,Resource cutter,int interior){var result=new List<Resource>();var inside=mesh;var used=new HashSet<string>();var data=new ModelMeshOperations.Snapshot(cutter);for(int f=0;f<data.Faces.Length;f++){if(inside.Get("faces").AsGodotArray().Count==0)break;var normal=data.Normal(f);float distance=normal.Dot(data.Center(f));string key=Variant.From(normal.Snapped(Vector3.One*.0001f)).ToString()+Variant.From(Mathf.Snapped(distance,.0001f)).ToString();if(!used.Add(key))continue;var outside=cut(inside,-normal,-distance,interior);if(outside.Get("faces").AsGodotArray().Count>0&&volume(outside)>.00000001)result.Add(outside);inside=cut(inside,normal,distance,interior);}return result;}
    public GArray subtract(Resource mesh,Resource cutter,int interior){var result=new GArray();foreach(var piece in Subtract(mesh,cutter,interior))result.Add(piece);return result;}
    private static int Root(int[] parents,int index){while(parents[index]!=index){parents[index]=parents[parents[index]];index=parents[index];}return index;}
    private List<Resource> Islands(Resource source){var data=new ModelMeshOperations.Snapshot(source);var parents=Enumerable.Range(0,data.Vertices.Length).ToArray();foreach(var face in data.Faces){if(face.Length==0)continue;for(int i=1;i<face.Length;i++)parents[Root(parents,face[i])]=Root(parents,face[0]);}var islands=new Dictionary<int,ModelGeometryOperations.Topology>();var mappings=new Dictionary<int,Dictionary<int,int>>();for(int f=0;f<data.Faces.Length;f++){var face=data.Faces[f];if(face.Length==0)continue;int id=Root(parents,face[0]);if(!islands.TryGetValue(id,out var mesh)){mesh=new ModelGeometryOperations.Topology{Smooth=data.Smooth};islands[id]=mesh;mappings[id]=new Dictionary<int,int>();}var mapping=mappings[id];var indices=new int[face.Length];for(int i=0;i<face.Length;i++){int vertex=face[i];if(!mapping.TryGetValue(vertex,out int mapped)){mapped=mesh.Points.Count;mapping[vertex]=mapped;mesh.Points.Add(data.Vertices[vertex]);}indices[i]=mapped;}mesh.AddFace(indices,data.Uv[f],data.Materials[f]);}return islands.Values.Select(mesh=>mesh.Build()).ToList();}
    public GArray solid_islands(Resource source){var result=new GArray();foreach(var mesh in Islands(source))result.Add(mesh);return result;}
    private static Settings Failure(string error)=>new Settings{["error"]=error,["parts"]=new GArray()};
    private static Aabb Bounds(Vector3[] points){var result=points.Length>0?new Aabb(points[0],Vector3.Zero):new Aabb();foreach(var point in points)result=result.Expand(point);return result;}
}
